A retried logical job retains its identifier. Provider is the local model of the documented idempotency contract. There are no production logs or provider traces.
class Worker:
    def process(self, job, provider, acknowledge):
        provider.send(job, idempotency_key=job)
        acknowledge(job)
class Provider:
    def __init__(self):
        self.delivered = {}
    def send(self, body, idempotency_key):
        if idempotency_key not in self.delivered:
            self.delivered[idempotency_key] = body
